// ChromaWing - UI Renderer
// v3.0

import { Parrot } from '../models/Parrot.js';
import { state, getNextParrotId } from '../game/gameState.js';
import { generateParrotSVG } from '../rendering/svgRenderer.js';
import { getBeautyColor, RARITY_COLORS, RARITY_LABELS, BODY_PARTS } from '../data/constants.js';
import { getRandomName } from '../utils/naming.js';
import { createParrotWithPurity } from '../utils/genetics.js';

// Update all UI elements
export async function updateUI() {
    updateStats();
    await renderParrotGrid();
    updateBreedingPanel();
    updateActionButtons();
}

// Update stats bar
export function updateStats() {
    document.getElementById('coinsDisplay').textContent = state.coins;
    document.getElementById('parrotCount').textContent = state.parrots.length;
    document.getElementById('maxGen').textContent = state.generation;
}

// Render parrot grid
export async function renderParrotGrid() {
    console.log('[Render] Rendering parrot grid...');
    console.log('[Render] Collection parrots:', state.parrots.length);
    console.log('[Render] Store parrots:', state.storeParrots.length);

    const collectionTab = document.getElementById('collectionTab');
    const storeTab = document.getElementById('storeTab');

    if (!collectionTab || !storeTab) {
        console.error('[Render] ERROR: Could not find tab elements!');
        return;
    }

    // Render collection
    collectionTab.innerHTML = '';
    for (const parrot of state.parrots) {
        console.log('[Render] Creating card for collection parrot:', parrot.name);
        const card = await createParrotCard(parrot, false);
        collectionTab.appendChild(card);
    }

    // Render store
    storeTab.innerHTML = '';
    for (const parrot of state.storeParrots) {
        console.log('[Render] Creating card for store parrot:', parrot.name);
        const card = await createParrotCard(parrot, true);
        storeTab.appendChild(card);
    }

    console.log('[Render] Grid rendering complete!');
}

// Create a parrot card
async function createParrotCard(parrot, isStore) {
    const card = document.createElement('div');
    card.className = 'parrot-card';

    if (state.selectedParrotId === parrot.id) {
        card.classList.add('selected');
    }

    // Generate SVG
    const svg = await generateParrotSVG(parrot);

    // Get stats
    const rarity = parrot.calculateRarity();
    const rarityInfo = {
        color: RARITY_COLORS[rarity],
        label: RARITY_LABELS[rarity]
    };
    const beauty = parrot.calculateBeauty();
    const beautyColor = getBeautyColor(beauty.score);
    const price = parrot.getValue();

    // Check if parrot is in breeding slots (show L/R indicator)
    let breedingIndicator = '';
    if (!isStore) {
        if (state.breedingPair.left === parrot.id) {
            breedingIndicator = '<div class="breeding-indicator breeding-left">L</div>';
        } else if (state.breedingPair.right === parrot.id) {
            breedingIndicator = '<div class="breeding-indicator breeding-right">R</div>';
        }
    }

    // Build card HTML
    card.innerHTML = `
        ${isStore ? `<div class="price">${price}💰</div>` : ''}
        ${breedingIndicator}
        <div class="parrot-mini">${svg}</div>
        <div class="parrot-name">${parrot.name}</div>
        <div class="parrot-gen">Gen ${parrot.generation}</div>
        <div class="rarity-badge" style="background: ${rarityInfo.color};">${rarityInfo.label}</div>
        <div class="beauty-badge" style="background: ${beautyColor}; color: white; font-size: 0.8em; padding: 2px 6px; border-radius: 4px; margin-top: 4px;">
            Beauty: ${Math.round(beauty.score)}
        </div>
        ${parrot.hasAnyGradients() ? '<div class="gradient-indicator">✨ Gradient</div>' : ''}
    `;

    // Click to select (both store and collection)
    card.onclick = () => {
        selectParrot(parrot.id);
    };

    return card;
}

// Update breeding panel
function updateBreedingPanel() {
    const leftSlot = document.getElementById('breedSlotLeft');
    const rightSlot = document.getElementById('breedSlotRight');
    const breedButton = document.getElementById('breedButton');

    if (state.breedingPair.left !== null) {
        const parrot = state.parrots.find(p => p.id === state.breedingPair.left);
        leftSlot.innerHTML = `
            <div class="slot-label">Left Parent</div>
            <div style="display: flex; align-items: center; justify-content: space-between;">
                <div>${parrot.name}</div>
                <button onclick="removeFromSlot('left')" style="background: #f44336; color: white; border: none; width: 24px; height: 24px; border-radius: 50%; cursor: pointer; font-size: 14px; line-height: 1; padding: 0;">&times;</button>
            </div>
        `;
    } else {
        leftSlot.innerHTML = `<div class="slot-label">Left Parent</div><div style="color: #ccc;">Empty</div>`;
    }

    if (state.breedingPair.right !== null) {
        const parrot = state.parrots.find(p => p.id === state.breedingPair.right);
        rightSlot.innerHTML = `
            <div class="slot-label">Right Parent</div>
            <div style="display: flex; align-items: center; justify-content: space-between;">
                <div>${parrot.name}</div>
                <button onclick="removeFromSlot('right')" style="background: #f44336; color: white; border: none; width: 24px; height: 24px; border-radius: 50%; cursor: pointer; font-size: 14px; line-height: 1; padding: 0;">&times;</button>
            </div>
        `;
    } else {
        rightSlot.innerHTML = `<div class="slot-label">Right Parent</div><div style="color: #ccc;">Empty</div>`;
    }

    // Enable breed button if both slots filled
    breedButton.disabled = !(state.breedingPair.left !== null && state.breedingPair.right !== null);
}

// Remove parrot from breeding slot
function removeFromSlot(slot) {
    if (slot === 'left') {
        state.breedingPair.left = null;
    } else if (slot === 'right') {
        state.breedingPair.right = null;
    }
    updateUI();
}

// Update action buttons for selected parrot
function updateActionButtons() {
    const actionSection = document.getElementById('topActionSection');
    const actionButtons = document.getElementById('actionButtons');

    if (!actionSection || !actionButtons) {
        console.warn('[Render] Action buttons container not found');
        return;
    }

    // Only show actions when a parrot is selected
    if (state.selectedParrotId === null || state.selectedParrotId === undefined) {
        actionSection.style.display = 'none';
        return;
    }

    // Check if parrot is in store or collection
    let parrot = state.parrots.find(p => p.id === state.selectedParrotId);
    let isInStore = false;

    if (!parrot) {
        parrot = state.storeParrots.find(p => p.id === state.selectedParrotId);
        isInStore = true;
    }

    if (!parrot) {
        actionSection.style.display = 'none';
        return;
    }

    actionSection.style.display = 'block';

    // Build action buttons based on whether it's a store or collection parrot
    if (isInStore) {
        const price = parrot.getValue();
        actionButtons.innerHTML = `
            <button class="btn btn-buy" onclick="buyParrot(${parrot.id})" ${state.coins < price ? 'disabled' : ''} style="background: #28a745; color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; font-weight: 600;">
                💰 Buy for ${price} coins
            </button>
        `;
    } else {
        const sellValue = Math.floor(parrot.getValue() * 0.7);
        actionButtons.innerHTML = `
            <button class="btn btn-breed-left" onclick="breedOnLeft(${parrot.id})" style="background: #667eea; color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; margin-right: 8px;">
                💕 Breed on Left
            </button>
            <button class="btn btn-breed-right" onclick="breedOnRight(${parrot.id})" style="background: #764ba2; color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; margin-right: 8px;">
                💕 Breed on Right
            </button>
            <button class="btn btn-sell" onclick="sellParrot(${parrot.id})" style="background: #ffc107; color: #333; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer; margin-right: 8px;">
                💵 Sell for ${sellValue} coins
            </button>
            <button class="btn btn-lab" onclick="openLaboratory(${parrot.id})" style="background: #17a2b8; color: white; border: none; padding: 8px 16px; border-radius: 6px; cursor: pointer;">
                🔬 Laboratory
            </button>
        `;
    }
}

// Select a parrot (just for preview - doesn't add to breeding slots)
function selectParrot(parrotId) {
    state.selectedParrotId = parrotId;
    updateUI();
}

// Add parrot to left breeding slot
function breedOnLeft(parrotId) {
    // Prevent selecting the same parrot in both slots
    if (state.breedingPair.right === parrotId) {
        return; // Silently prevent
    }
    state.breedingPair.left = parrotId;
    updateUI();
}

// Add parrot to right breeding slot
function breedOnRight(parrotId) {
    // Prevent selecting the same parrot in both slots
    if (state.breedingPair.left === parrotId) {
        return; // Silently prevent
    }
    state.breedingPair.right = parrotId;
    updateUI();
}

// Buy parrot from store
function buyParrot(parrotId) {
    const parrot = state.storeParrots.find(p => p.id === parrotId);
    if (!parrot) return;

    const price = parrot.getValue();

    if (state.coins < price) {
        alert('Not enough coins!');
        return;
    }

    state.coins -= price;
    state.parrots.push(parrot);
    state.storeParrots = state.storeParrots.filter(p => p.id !== parrotId);

    // Generate replacement parrot with similar rarity
    const oldRarity = parrot.calculateRarity();
    let newParrot = null;
    let attempts = 0;
    const maxAttempts = 50;

    while (attempts < maxAttempts && !newParrot) {
        attempts++;

        let genes;
        if (oldRarity === 'legendary') {
            genes = createParrotWithPurity('high');
            // Add gradients to 2-3 body parts for legendary
            const numGradients = 2 + Math.floor(Math.random() * 2);
            for (let j = 0; j < numGradients; j++) {
                const part = BODY_PARTS[Math.floor(Math.random() * BODY_PARTS.length)];
                genes[part].gradient = true;
            }
        } else if (oldRarity === 'epic') {
            genes = createParrotWithPurity('high');
        } else if (oldRarity === 'rare') {
            genes = createParrotWithPurity('medium');
        } else if (oldRarity === 'uncommon') {
            genes = createParrotWithPurity('low');
        } else {
            genes = createParrotWithPurity('random');
        }

        const testParrot = new Parrot(getRandomName(), genes, 1);
        const actualRarity = testParrot.calculateRarity();

        // Accept if rarity matches or we're on last attempt
        if (actualRarity === oldRarity || attempts >= maxAttempts) {
            newParrot = testParrot;
        }
    }

    if (newParrot) {
        state.storeParrots.push(newParrot);
    }

    // Clear selection
    state.selectedParrotId = null;

    // Show success toast
    if (window.showToast) {
        const rarity = parrot.calculateRarity();
        window.showToast(
            `${parrot.name} joined your collection!`,
            `${rarity.charAt(0).toUpperCase() + rarity.slice(1)} • Gen ${parrot.generation} • -${price} coins`,
            'success'
        );
    }

    updateUI();

    // Check achievements
    if (window.checkAchievements) {
        window.checkAchievements();
    }
}

// Export for window
export { selectParrot, buyParrot, breedOnLeft, breedOnRight, removeFromSlot };
